var topKFrequent = function (nums, k) {
    const freq = new Map();
    for (const x of nums) freq.set(x, (freq.get(x) || 0) + 1);
    // minimal binary min-heap of [value, count] ordered by count
    const heap = [];
    const swap = (i, j) => ([heap[i], heap[j]] = [heap[j], heap[i]]);
    const push = (item) => {
        heap.push(item);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p][1] <= heap[i][1]) break;
            swap(i, p);
            i = p;
        }
    };
    const pop = () => {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length > 0) {
            heap[0] = last;
            let i = 0;
            while (true) {
                const l = 2 * i + 1,
                    r = l + 1;
                let s = i;
                if (l < heap.length && heap[l][1] < heap[s][1]) s = l;
                if (r < heap.length && heap[r][1] < heap[s][1]) s = r;
                if (s === i) break;
                swap(i, s);
                i = s;
            }
        }
        return top;
    };
    for (const entry of freq) {
        push(entry);
        if (heap.length > k) pop(); // drop the least frequent
    }
    return heap.map((e) => e[0]);
};

