class Solution {

    public boolean isValidSudoku(char[][] board) {
        for (int r = 0; r < 9; r++) {
            // rows
            Set<Character> seen = new HashSet<>();
            for (int c = 0; c < 9; c++) {
                char ch = board[r][c];
                if (ch != '.' && !seen.add(ch)) return false;
            }
        }
        for (int c = 0; c < 9; c++) {
            // columns
            Set<Character> seen = new HashSet<>();
            for (int r = 0; r < 9; r++) {
                char ch = board[r][c];
                if (ch != '.' && !seen.add(ch)) return false;
            }
        }
        for (int b = 0; b < 9; b++) {
            // boxes
            Set<Character> seen = new HashSet<>();
            int r0 = (b / 3) * 3,
                c0 = (b % 3) * 3; // top-left of box b
            for (int r = r0; r < r0 + 3; r++) {
                for (int c = c0; c < c0 + 3; c++) {
                    char ch = board[r][c];
                    if (ch != '.' && !seen.add(ch)) return false;
                }
            }
        }
        return true;
    }
}

