class Solution {

    public int longestConsecutive(int[] nums) {
        int best = 0;
        for (int x : nums) {
            int cur = x,
                len = 1;
            while (linearSearch(nums, cur + 1)) {
                // walk upward while next value exists
                cur++;
                len++;
            }
            best = Math.max(best, len);
        }
        return best;
    }

    private boolean linearSearch(int[] nums, int target) {
        for (int v : nums) if (v == target) return true;
        return false;
    }
}

