        for (int x : nums) {
            if (x == c1) cnt1++;
            else if (x == c2) cnt2++;
        }
        List<Integer> res = new ArrayList<>();
        if (cnt1 > nums.length / 3) res.add(c1);
        if (cnt2 > nums.length / 3) res.add(c2);
        return res;
    }
}

