class Solution {

    public long numberOfInversions(int[] nums) {
        int[] temp = new int[nums.length];
        return sortCount(nums, temp, 0, nums.length - 1);
    }

    private long sortCount(int[] a, int[] temp, int low, int high) {
        if (low >= high) return 0;
        int mid = low + (high - low) / 2;
        long count =
            sortCount(a, temp, low, mid) +
            sortCount(a, temp, mid + 1, high);
        int i = low,
            j = mid + 1,
            k = low;
        while (i <= mid && j <= high) {
            if (a[i] <= a[j]) temp[k++] = a[i++];
            // not an inversion (equal is not counted)
            else {
                count += mid - i + 1; // a[i..mid] are all > a[j]
                temp[k++] = a[j++];
            }
        }
        while (i <= mid) temp[k++] = a[i++];
        while (j <= high) temp[k++] = a[j++];
        for (int p = low; p <= high; p++) a[p] = temp[p];
        return count;
    }
}

