class Solution {

    public int reversePairs(int[] nums) {
        return sortCount(
            nums,
            new int[nums.length],
            0,
            nums.length - 1
        );
    }

    private int sortCount(int[] a, int[] temp, int low, int high) {
        if (low >= high) return 0;
        int mid = low + (high - low) / 2;
        int count =
            sortCount(a, temp, low, mid) +
            sortCount(a, temp, mid + 1, high);
        // count pass: both halves are sorted, j only moves forward
        int j = mid + 1;
        for (int i = low; i <= mid; i++) {
            while (j <= high && (long) a[i] > 2L * a[j]) j++;
            count += j - (mid + 1); // a[mid+1 .. j-1] all pair with a[i]
        }
        // standard merge
        int i = low,
            k = low;
        j = mid + 1;
        while (i <= mid && j <= high)
            temp[k++] = a[i] <= a[j] ? a[i++] : a[j++];
        while (i <= mid) temp[k++] = a[i++];
        while (j <= high) temp[k++] = a[j++];
        for (int p = low; p <= high; p++) a[p] = temp[p];
        return count;
    }
}

