class Solution {

    public int maxSubArrayLen(int[] nums, int k) {
        Map<Long, Integer> firstIndex = new HashMap<>();
        firstIndex.put(0L, -1); // empty prefix
        long prefix = 0;
        int best = 0;
        for (int i = 0; i < nums.length; i++) {
            prefix += nums[i];
            Integer j = firstIndex.get(prefix - k);
            if (j != null) best = Math.max(best, i - j); // subarray (j, i]
            firstIndex.putIfAbsent(prefix, i); // keep EARLIEST index for max length
        }
        return best;
    }
}

